-- Thread 1 (sort 312): the-watcher-rebellion-as-the-stumbling-block-architecture-in-1-enoch
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-watcher-rebellion-as-the-stumbling-block-architecture-in-1-enoch',
       'The Watcher-rebellion as the stumbling-block architecture — 1 Enoch 8-27 read against Matt 18:6-9''s millstone-warning + sin-amputation + gehenna (FRAMEWORK-MAJOR)',
       'Matt 18:6-9''s millstone-warning against offending the little-ones-who-believe + the sin-amputation against the disciple''s-own-stumbling-substance + the gehenna-of-fire-judgment — read against the wisdom-stream''s articulation of the original-stumbling-block architecture in 1 Enoch. Five moves: 1 Enoch 8:1 names THE architectural-root of the *skandalon* substance — the watchers'' teaching of the corrupting-arts (weapons, antimony-for-the-eyelids, costly stones, colouring-tinctures) the substance-of-which placed-the-stumbling-blocks across the way of the walker; 1 Enoch 10:8 names the whole earth''s-corruption-through-the-watcher-taught-substance — the architecture under the King''s *it must needs be that offences come* (Matt 18:7); 1 Enoch 19:1 names the lying-spirits-leading-astray in many-forms across the present-age — the architecture under every-system-of-stumbling-block the King''s millstone-warning lands-on (the institutional-Christianity''s antinomian-doctrine, the Hebrew-Roots false-inclusion gospel, the Pharisaic-traditions-of-the-elders, the Galatian-circumcision-party, the Islamic-transfer — the four-costumes per voice skill framework); 1 Enoch 22:11 names the place-of-the-eternal-judgment for those who-perpetuated-the-substance — the consummation-of-the-judgment the King names as *better* than the millstone-and-the-sea-mercy; 1 Enoch 27:2 names THE direct verbal-anchor for the accursed-valley-of-judgment substance — the Watcher-Book passage describing the valley at the centre of the holy mountain that pre-figures the *gei-Hinnom* (Valley of the sons of Hinnom) on the southern-edge of Yerushalayim (Jerusalem) the King''s gehenna names. The framework reads the cluster as FRAMEWORK-MAJOR: the wisdom-stream''s articulation of the seed-war operating architecturally from the watcher-fall through the present-age is the architecture under the inevitability-of-offences the King names; the woe-to-the-man-by-whom-the-offence-cometh is the same architecture 1 Enoch names the eternal judgment-substance for; the gehenna-substance is the Tanakh-and-wisdom-stream''s accursed-valley-of-judgment carried-forward, NOT the inherited-Christian-eternal-conscious-torment doctrine read-back into the substance. The little-ones-led-astray are victims-not-enemies per voice skill''s patience-not-condescension posture; the systems-and-the-leadership-who-perpetuate-the-corruption are where the woe lands.',
       sv.verse_id, ev.verse_id, 'complete_study', 312
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 18 AND sv.verse_number = 6
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 18 AND ev.verse_number = 9
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 313): the-lord-of-the-sheep-and-the-gathering-in-the-animal-apocalypse
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-lord-of-the-sheep-and-the-gathering-in-the-animal-apocalypse',
       'The Lord of the sheep and the gathering — 1 Enoch''s Animal Apocalypse (ch 89-90) read against Matt 18:10-14''s despise-not-the-little-ones + their-angels + the lost-sheep parable (FRAMEWORK-MAJOR)',
       'Matt 18:10-14''s pivot — the despise-not-the-little-ones warning + the guardian-messengers-behold-the-face-of-my-Father substance + the Son-of-Adam-is-come-to-save-the-lost mission-statement + the lost-sheep-shepherd parable + the Father''s-will-substance — read against the wisdom-stream''s most-direct shepherd-substance running-in-parallel with Yechezk''el (Ezekiel) 34''s Tanakh-shepherd-substance. Five moves: 1 Enoch 40:9 names the wisdom-stream''s articulation of the four-presences-before-the-Father — Michael the merciful-and-long-suffering, Raphael over sickness-and-wounds, Gabriel over the powers, Phanuel over the repentance-unto-hope — the messengers'' direct-throne-access architecture the King names at v.10 (*in heaven their angels do always behold the face of my Father*); 1 Enoch 89:42 names the Lord-of-the-sheep''s-acting-substance against the beasts-and-birds-of-the-heaven who devour the sheep — the wisdom-stream''s Animal-Apocalypse carrying-forward of the Tanakh-Yechezk''el (Ezekiel) 34 shepherd-substance into apocalyptic-vision-form; 1 Enoch 89:54 names THE direct verbal-anchor for the Lord-of-the-sheep-title-substance — the wisdom-stream identifies the Lord-of-the-sheep with Yahuah by name; 1 Enoch 90:6 names the lambs-that-open-their-eyes-substance the post-judgment opening-of-the-eyes-of-the-sheep-who-had-been-blinded; 1 Enoch 90:18 names the consummation-rejoicing the Lord-of-the-sheep walks-toward — *all feared the Lord of the sheep, and they began to fall down upon his face and to worship him* — the wisdom-stream''s articulation of the gathering-substance the King''s shepherd-parable enacts at the historical-pivot. The framework reads the cluster as FRAMEWORK-MAJOR per Red Line #7''s reading of the lost-sheep-of-the-house-of-Yashar''el (Israel) mission-scope: the Matt 18 shepherd-parable lands at two-levels-simultaneously — the assembly''s-internal-little-ones AND the canon-wide lost-sheep-of-the-house-of-Yashar''el (Israel) mission-scope per Matt 10:6 and Matt 15:24. Both levels derive from the same Lord-of-the-sheep architecture 1 Enoch had carried-forward from Yechezk''el (Ezekiel) 34. The cause-and-effect-of-hearing per Red Line #11 operates in the architecture of the lambs-who-open-the-eyes being-the-substance who-hear-when-the-Shepherd-calls; the gathering is the Father''s-will-substance per v.14, not the universalist-overriding-determinism.',
       sv.verse_id, ev.verse_id, 'complete_study', 313
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 18 AND sv.verse_number = 10
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 18 AND ev.verse_number = 14
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 314): the-reproof-and-restoration-procedure-in-sirach
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-reproof-and-restoration-procedure-in-sirach',
       'The reproof-and-restoration procedure — Sirach (Ecclesiasticus) 19-20''s wisdom-stream witness to Matt 18:15-17''s four-step assembly-discipline pattern',
       'Matt 18:15-17''s four-step assembly-discipline procedure — *go and tell him his fault between thee and him alone* → *take with thee one or two more, that in the mouth of two or three witnesses every word may be established* → *tell it unto the assembly* → *let him be unto thee as an heathen man and a publican* — read against the wisdom-stream''s articulation of the reproof-and-restoration procedure in Sirach (Ecclesiasticus). Four moves: Sirach 19:13 names THE direct verbal-anchor for the first-step private-confrontation substance (*admonish a friend, it may be he has not done it: and if he have done it, that he may do it no more*) — the wisdom-stream had named the substance the King institutionalizes; Sirach 19:17 names the disposition-the-rebuker-walks-in (*admonish your neighbour before you threaten him; and not being angry, give place to the law of the Most High*) — the order and the inner-substance; Sirach 19:15 names the substance the witness-verification-procedure protects against (*for many times it is a slander, and believe not every tale*) — the architecture the King''s two-or-three-witnesses applies the Tanakh-Devarim (Deuteronomy) 19:15 evidentiary-standard for; Sirach 20:2 names the substance of the open-reproof (*it is much better to reprove, than to be angry secretly: and he that confesseth his fault shall be preserved from hurt*) — the architecture under the King''s step-three assembly-level confrontation. The framework reads the cluster as the wisdom-stream''s direct-prefiguring of the King''s assembly-discipline pattern at the procedural-register the King will institutionalize. The substance is restoration-aimed at every step — *if he shall hear thee, thou hast gained thy brother* (v.15) is the desired-outcome of the wisdom-stream''s instruction; the framework reads this in continuity with Vayikra (Leviticus) 19:17''s *thou shalt in any wise rebuke thy neighbour* Tanakh-anchor and Galatians 6:1''s apostolic-restatement *restore such an one in the spirit of meekness.* The framework rules out the institutional-Christian-collapse of step-four into permanent-shunning-and-condemnation — the substance is disposition-shift from internal-assembly-member to mission-target per the patience-not-condescension posture, NOT condemnation-to-permanent-exclusion.',
       sv.verse_id, ev.verse_id, 'complete_study', 314
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 18 AND sv.verse_number = 15
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 18 AND ev.verse_number = 17
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 315): forgive-and-be-forgiven-the-mercy-met-with-mercy-architecture
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'forgive-and-be-forgiven-the-mercy-met-with-mercy-architecture',
       'Forgive and be forgiven — the mercy-met-with-mercy architecture in Sirach (Ecclesiasticus) 27-28 and Testament of Gad read against Matt 18:21-35''s seventy-times-seven + unforgiving-servant parable + heart-Torah closing (FRAMEWORK-MAJOR)',
       'Matt 18:21-35''s unified forgiveness-arc — Kefa (Peter)''s *till seven times?* question + the King''s *seventy times seven* answer inverting Lamekh (Lamech)''s *if Cain shall be avenged sevenfold, truly Lamekh (Lamech) seventy and sevenfold* at Bereshit (Genesis) 4:24 + the unforgiving-servant parable + the chapter-closing *so likewise shall my heavenly Father do also unto you, if ye from your hearts forgive not* — read against the wisdom-stream''s most-direct prefiguring in Sirach (Ecclesiasticus) 27-28 and Testament of Gad. Five moves: Sirach 27:30 names the wisdom-stream''s articulation of the disposition-the-King-is-forming-against — *malice and wrath, even these are abominations* — the substance Kefa''s *how oft shall my brother sin against me, and I forgive him? till seven times?* is still operating within; Sirach 28:2 names THE direct verbal-anchor for the conditional-forgiveness-architecture — *forgive your neighbour the hurt that he has done to you, so shall your sins also be forgiven when you prayest* — the same conditional-substance the King''s parable extends into full narrative-form and the chapter-closing v.35 *if ye from your hearts forgive not* locks; Sirach 28:3 names THE direct verbal-anchor for the unforgiving-servant''s-grotesque-architecture — *one man bears hatred against another, and does he seek pardon from Yahuah (God)?* — the architecture the King''s lord-of-the-parable names at v.33 (*shouldest not thou also have had compassion on thy fellowservant, even as I had pity on thee?*); Sirach 28:7 names the wisdom-stream''s articulation of the heart-Torah-substance — *remember the commandments, and bear no malice to your neighbour: remember the covenant of the Highest, and wink at ignorance* — the Torah-internalized-and-the-substance-of-no-malice as one-substance-not-two; Testament of Gad 62:3 names the wisdom-stream''s heart-substance + speak-peaceably-to-the-sinning-brother substance (*love ye one another from the heart; and if a man sin against thee, speak peaceably to him*) the King''s assembly-arc operationalizes at vv.15-17 AND v.35. The framework reads the cluster as FRAMEWORK-MAJOR: the wisdom-stream had named the architecture of mercy-met-with-mercy at the wisdom-instruction-register; the King institutionalizes the same architecture at the kingdom-citizens'' corporate-register and parable-extends it into full-narrative-form. The framework rules out the institutional-Christian-once-saved-always-saved doctrine — the lord-revokes the forgiveness when the disposition-the-forgiveness-was-given-to-form does not form; the cross opens the door home, the door remains real (1 Corinthians 9:27''s *lest by any means... I myself should be a castaway*). The framework reads this in continuity with Yirmeyahu (Jeremiah) 31:33''s new-covenant law-in-the-inward-parts and Yechezk''el (Ezekiel) 36:26-27''s new-heart-and-Spirit-causing-the-walking — the wisdom-stream''s substance the King brings to-completion at the cross-and-the-Spirit-and-the-walking the assembly is-being-formed-into.',
       sv.verse_id, ev.verse_id, 'complete_study', 315
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 18 AND sv.verse_number = 21
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 18 AND ev.verse_number = 35
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 316): the-greatness-as-humility-and-the-proud-cast-down-in-the-wisdom-stream
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-greatness-as-humility-and-the-proud-cast-down-in-the-wisdom-stream',
       'Greatness as humility and the proud cast down — Sirach (Ecclesiasticus) 3 and 10''s wisdom-stream witness to Matt 18:1-5''s greatness-as-child kingdom-inversion',
       'Matt 18:1-5''s opening movement — the disciples'' v.1 hierarchy-question (*who is the greatest in the kingdom of heaven?*) + the King''s-acted-parable of a little child set in the midst + the *except ye be converted, and become as little children, ye shall not enter into the kingdom of heaven* substance + the *whosoever therefore shall humble himself as this little child, the same is greatest in the kingdom of heaven* inversion + the *whoso shall receive one such little child in my name receiveth me* extension — read against the wisdom-stream''s direct articulation of the kingdom-inversion-of-greatness substance. Three moves: Sirach (Ecclesiasticus) 10:7 names the wisdom-stream''s articulation of the disposition-the-King-is-confronting at the disciples'' v.1 hierarchy-question — *pride is hateful before Yahuah (God) and man: and by both does one commit iniquity*; Sirach 3:18 names THE direct verbal-anchor for the kingdom-inversion-of-greatness substance — *the greater you are, the more humble thyself, and you shall find favour before Yahuah (God)* — the wisdom-stream had named the substance the King teaches at the assembly-disposition register; Sirach 10:14 names THE direct verbal-anchor for the kingdom-inversion-of-thrones substance — *Yahuah (God) has cast down the thrones of proud princes, and set up the meek in their stead* — the wisdom-stream''s articulation of the same inversion the King names at v.4, with the eschatological-day-of-the-Father pre-figuring at Mary''s Magnificat (Luke 1:51-52''s *he hath put down the mighty from their seats, and exalted them of low degree*) and the apostolic-restatement at 1 Corinthians 1:26-29 (*Elohim (God) hath chosen the foolish things of the world to confound the wise*). The framework reads the cluster in continuity with the Tanakh-*anawim* (humble-poor) substance pattern (Tehillim (Psalm) 131:1-2''s weaned-child; Tehillim (Psalm) 8:2''s out-of-the-mouth-of-babes; Yeshayahu (Isaiah) 11:6''s little-child-shall-lead-them; Yeshayahu (Isaiah) 57:15''s contrite-and-humble-spirit; Yeshayahu (Isaiah) 66:2''s poor-and-of-a-contrite-spirit; Mishlei (Proverbs) 22:4''s humility-and-the-fear-of-Yahuah). The apostolic-restatement at 1 Peter 5:5 (citing Mishlei (Proverbs) 3:34) and Yaaqov (James) 4:10 lands the substance at the apostolic-kingdom-citizens'' disposition-register. The kingdom-citizen''s-greatness is measured by the depth of the humility-substance, not by the height of the position-substance. The framework rules out the institutional-Christian-individualistic-power-grasping inversion-fail and the Hebrew-Roots false-inclusion universalization-of-the-child-substance into a generic-everyone-can-be-saved substance.',
       sv.verse_id, ev.verse_id, 'complete_study', 316
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 18 AND sv.verse_number = 1
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 18 AND ev.verse_number = 5
ON CONFLICT (slug) DO NOTHING;

