-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s155_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 18
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'the-watcher-rebellion-as-the-stumbling-block-architecture-in-1-enoch',
     'the-lord-of-the-sheep-and-the-gathering-in-the-animal-apocalypse',
     'the-reproof-and-restoration-procedure-in-sirach',
     'forgive-and-be-forgiven-the-mercy-met-with-mercy-architecture',
     'the-greatness-as-humility-and-the-proud-cast-down-in-the-wisdom-stream'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'the-watcher-rebellion-as-the-stumbling-block-architecture-in-1-enoch',
     'the-lord-of-the-sheep-and-the-gathering-in-the-animal-apocalypse',
     'the-reproof-and-restoration-procedure-in-sirach',
     'forgive-and-be-forgiven-the-mercy-met-with-mercy-architecture',
     'the-greatness-as-humility-and-the-proud-cast-down-in-the-wisdom-stream'
   );

  RAISE NOTICE 'S155 Matt 18 verify: extras xrefs from canon/matthew/18 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 22 THEN
    RAISE EXCEPTION 'Expected at least 22 Matt-18 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 22 THEN
    RAISE EXCEPTION 'Expected at least 22 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
